package com.primehr.succession.domain;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="succession_committee_charter_version",uniqueConstraints=@UniqueConstraint(name="uk_succ_charter_version",columnNames={"agency_id","charter_id","definition_version"}))
public class SuccessionCommitteeCharterVersion extends SuccessionVersionedDefinition {
 public enum QuorumType{COUNT,PERCENTAGE}
 @Column(name="charter_id",nullable=false,length=36) private String charterId; @Column(name="legal_basis",nullable=false,length=2000) private String legalBasis; @Column(name="authority_reference",nullable=false,length=250) private String authorityReference; @Enumerated(EnumType.STRING) @Column(name="quorum_type",nullable=false,length=20) private QuorumType quorumType; @Column(name="quorum_value",nullable=false,precision=7,scale=2) private BigDecimal quorumValue; @Column(name="requires_secretariat",nullable=false) private boolean requiresSecretariat; @Column(name="requires_agency_head_decision",nullable=false) private boolean requiresAgencyHeadDecision; @Column(name="conflict_declaration_required",nullable=false) private boolean conflictDeclarationRequired; @Column(name="roster_revision",nullable=false) private int rosterRevision;
 protected SuccessionCommitteeCharterVersion(){}
 public SuccessionCommitteeCharterVersion(String agencyId,String charterId,int version,String supersedes,String title,String description,String legalBasis,String authority,QuorumType type,BigDecimal value,boolean secretariat,boolean agencyHead,boolean conflict){super(agencyId,version,supersedes,title,description);this.charterId=requiredText(charterId,"charterId");apply(legalBasis,authority,type,value,secretariat,agencyHead,conflict);}
 public void update(String title,String description,String legalBasis,String authority,QuorumType type,BigDecimal value,boolean secretariat,boolean agencyHead,boolean conflict){changeDefinition(title,description);apply(legalBasis,authority,type,value,secretariat,agencyHead,conflict);} public void rosterChanged(){requireDraft();rosterRevision++;}
 private void apply(String legalBasis,String authority,QuorumType type,BigDecimal value,boolean secretariat,boolean agencyHead,boolean conflict){if(type==null||value==null||value.signum()<=0)throw new IllegalArgumentException("Positive quorum is required");if(type==QuorumType.PERCENTAGE&&value.compareTo(new BigDecimal("100"))>0)throw new IllegalArgumentException("Percentage quorum cannot exceed 100");if(type==QuorumType.COUNT&&value.stripTrailingZeros().scale()>0)throw new IllegalArgumentException("Count quorum must be whole");this.legalBasis=requiredText(legalBasis,"legalBasis");authorityReference=requiredText(authority,"authorityReference");quorumType=type;quorumValue=value;requiresSecretariat=secretariat;requiresAgencyHeadDecision=agencyHead;conflictDeclarationRequired=conflict;}
 public String getCharterId(){return charterId;} public String getLegalBasis(){return legalBasis;} public String getAuthorityReference(){return authorityReference;} public QuorumType getQuorumType(){return quorumType;} public BigDecimal getQuorumValue(){return quorumValue;} public boolean isRequiresSecretariat(){return requiresSecretariat;} public boolean isRequiresAgencyHeadDecision(){return requiresAgencyHeadDecision;} public boolean isConflictDeclarationRequired(){return conflictDeclarationRequired;} public int getRosterRevision(){return rosterRevision;}
}
